$g=[IO.File]::ReadAllText($(if($env:MK_SRC){$env:MK_SRC}else{'C:\claudecode\dark raiders\dark_raiders.html'}))
function L([string]$rx){ $m=[regex]::Matches($g,$rx); if($m.Count -ne 1){ throw "anchor $rx matched $($m.Count)" }; return $m[0].Value.Replace("`r",'') }
$a1=L "dangerPlate:'rgba\(40,8,6,\.84\)', ink:INK\};"
$r1=$a1+"`n// v34.69 (cw-hudpanel1), the critic on screens 47, 48 and 51 (every corner has a differently shaped box): ONE corner panel look, the fill of HUDC.plate, a 1px line and a 4px radius. hudPlate and hudPanel both read it (hudPanel had a cut corner, hudPlate had no line).`nvar HUDPS={fill:HUDC.plate, line:'rgba(112,122,130,.95)', rad:4};"
$a2=L "function hudPlate\(x,y,w,h,accent,fill\)\{[\s\S]*?\r?\n\}\r?\nfunction hudText"
$r2=@'
function hudPlate(x,y,w,h,accent,fill){
  if(!(w>0&&h>0)) return;
  var r=Math.max(0,Math.min(LH(HUDPS.rad),h/2,w/2));
  ctx.fillStyle=fill||HUDPS.fill;
  ctx.beginPath();
  if(ctx.roundRect) ctx.roundRect(x,y,w,h,r);
  else { ctx.moveTo(x+r,y); ctx.arcTo(x+w,y,x+w,y+h,r); ctx.arcTo(x+w,y+h,x,y+h,r); ctx.arcTo(x,y+h,x,y,r); ctx.arcTo(x,y,x+w,y,r); ctx.closePath(); }
  ctx.fill();
  ctx.beginPath();   // v34.69 (cw-hudpanel1): the shared 1px line
  if(ctx.roundRect) ctx.roundRect(x+.5,y+.5,w-1,h-1,Math.max(0,r-.5));
  else ctx.rect(x+.5,y+.5,w-1,h-1);
  ctx.strokeStyle=HUDPS.line; ctx.lineWidth=1; ctx.stroke();
  if(accent){ ctx.fillStyle=accent; ctx.fillRect(x,y+r*0.5,Math.max(2,LH(3)),h-r); }
}
function hudText
'@.Replace("`r",'').TrimEnd("`n")
$a3=L "  c=Math\.max\(0,Math\.min\(10,w/3,h/3\)\); a=\(a===undefined\)\?0\.88:a;\r?\n  function path\(px,py,pw,ph,pc\)\{[^\r\n]*\}"
$r3="  c=Math.max(0,Math.min(LH(HUDPS.rad),w/3,h/3)); a=(a===undefined)?0.88:a;   // v34.69 (cw-hudpanel1): the shared 4px radius, not a cut corner`n  function path(px,py,pw,ph,pc){ ctx.beginPath(); if(ctx.roundRect) ctx.roundRect(px,py,pw,ph,pc); else ctx.rect(px,py,pw,ph); }"
$a4=L "ctx\.strokeStyle='rgba\(112,122,130,\.95\)'; ctx\.lineWidth=1; ctx\.stroke\(\);   // v28\.xx \(cw-panelflat\)"
$r4="ctx.strokeStyle=HUDPS.line; ctx.lineWidth=1; ctx.stroke();   // v28.xx (cw-panelflat)"
$chk=@'
  {v:'VER',what:'the corner panels share one fill, one line and one radius (hudPlate and hudPanel read HUDPS; the critic: every corner has a differently shaped box)',
   run:function(){
     if(typeof HUDPS==='undefined') return 'no shared corner panel style (HUDPS)';
     if(HUDPS.fill!==HUDC.plate) return 'the panel fill is not the HUD plate fill';
     if(!(HUDPS.rad===4)) return 'the radius is '+HUDPS.rad+', not 4';
     var a=String(hudPlate), b=String(hudPanel);
     if(a.indexOf('HUDPS.fill')<0||a.indexOf('HUDPS.line')<0) return 'hudPlate does not read the shared fill and line';
     if(b.indexOf('HUDPS.line')<0||b.indexOf('HUDPS.rad')<0) return 'hudPanel does not read the shared line and radius';
     if(b.indexOf('lineTo')>=0) return 'hudPanel still draws a cut corner';
     return null; }},
'@.Replace("`r",'')
$d=[ordered]@{
  title='ONE CORNER PANEL LOOK'
  why='The critic on screens 47, 48 and 51: every corner has a differently shaped box. The ammo and gun panels had a cut corner, the plates had no line. Both now draw the same fill, 1px line and 4px radius.'
  now='The raid hud panels (score, ammo, log rows, controls) all share one fill, one border and 4px round corners.'
  edits=@( [ordered]@{ anchor=$a1; replacement=$r1 }, [ordered]@{ anchor=$a2; replacement=$r2 }, [ordered]@{ anchor=$a3; replacement=$r3 }, [ordered]@{ anchor=$a4; replacement=$r4 } )
  check=$chk
}
[IO.File]::WriteAllText('C:\claudecode\dark raiders\tools\handoff\drafts\draft-cw-hudpanel1.json',($d | ConvertTo-Json -Depth 6),(New-Object Text.UTF8Encoding $false))
